        auto last_tmp = Clock::now();
        while (ms_since(start) < cap_ms) {
            if (tmp_sibling_exists(file))
                last_tmp = Clock::now();
            else if (ms_since(last_tmp) >= quiet_ms)
                return true;
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
        return false;
    }

    void measure(std::size_t triangles, std::uintmax_t stl_bytes)
    {
        boost::system::error_code ec;
        Model& model = m_plater->model();

        // 1. Thin file: what auto-backup writes (SaveStrategy::Backup), UI thread.
        for (int run = 0; run < 3; ++run) {
            const fs::path out = m_state->scratch / ("thin-" + std::to_string(triangles) + "-" + std::to_string(run) + ".3mf");
            fs::remove(out, ec);
            const auto start = Clock::now();
            const int rc = m_plater->export_3mf(out, SaveStrategy::Backup);
            const double ms = ms_since(start);
            const auto bytes = rc >= 0 ? fs::file_size(out, ec) : 0;
            std::cerr << "BENCH THIN triangles=" << triangles << " run=" << run << " rc=" << rc << " thin_ms=" << ms
                      << " file_bytes=" << bytes << " main_thread=" << wxIsMainThread() << '\n';
        }

        // 2. Full project export via the workspace adapter (comparison).
        {
            OrcaWorkspaceAdapter workspace(*m_plater);
            for (int run = 0; run < 3; ++run) {
                const fs::path out = m_state->scratch / ("export-" + std::to_string(triangles) + "-" + std::to_string(run) + ".3mf");
                const auto start = Clock::now();
                const CommandResult result = workspace.export_project_archive(out.string());
                const double ms = ms_since(start);
                const auto bytes = result.succeeded() ? fs::file_size(out, ec) : 0;
                std::cerr << "BENCH EXPORT triangles=" << triangles << " stl_bytes=" << stl_bytes << " run=" << run
                          << " ok=" << result.succeeded() << " export_ms=" << ms << " file_bytes=" << bytes
                          << " main_thread=" << wxIsMainThread() << '\n';
            }
        }

        // 3. Per-object mesh file written by the backup manager thread.
        if (!model.is_need_backup()) {
            std::cerr << "BENCH NOTE need_backup was false at measure time; calling set_need_backup()\n";
            model.set_need_backup();
        }
        ModelObject* object = model.objects.front();
        const std::string backup_path = model.get_backup_path();
        const int backup_id = model.get_object_backup_id(*object);
        const fs::path mesh_file = fs::path(backup_path) / "3D" / "Objects" / (object->name + "_" + std::to_string(backup_id) + ".model");
        std::cerr << "BENCH MESHFILE_PATH triangles=" << triangles << " need_backup=" << model.is_need_backup()
                  << " object_name=" << object->name << " backup_id=" << backup_id
                  << " backup_path_empty=" << backup_path.empty() << " path=" << mesh_file.string()
                  << " exists_before=" << fs::exists(mesh_file, ec) << '\n';
        if (backup_path.empty()) {
            std::cerr << "BENCH MESHFILE triangles=" << triangles << " error=backup_path_empty\n";
        } else {
            for (int run = 0; run < 3; ++run) {
                // Drain any pending write (the load itself queues one) before we start the clock.
                const bool quiet = wait_writer_quiet(mesh_file, 500.0, 30000.0);
                fs::remove(mesh_file, ec);
                const auto start = Clock::now();
                Slic3r::save_object_mesh(*object);
                const double sync_ms = ms_since(start);
                std::uintmax_t last_size = 0;
                int stable = 0;
                bool done = false;
                while (ms_since(start) < 30000.0) {
                    if (fs::exists(mesh_file, ec) && !tmp_sibling_exists(mesh_file)) {
                        const auto size = fs::file_size(mesh_file, ec);
                        stable = (size == last_size) ? stable + 1 : 0;
                        last_size = size;
                        if (stable >= 3) { done = true; break; }
                    } else {
                        stable = 0;
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds(1));
                }
                const double ms = ms_since(start);
                std::cerr << "BENCH MESHFILE triangles=" << triangles << " run=" << run << " ok=" << done
                          << " writer_quiet_before=" << quiet << " sync_call_ms=" << sync_ms
                          << " elapsed_ms=" << ms << " file_bytes=" << (done ? last_size : 0) << '\n';
            }

            // 4. Hash cost: read the mesh file into memory, SHA-256 it (OpenSSL via sha256_hex).
            for (int run = 0; run < 3; ++run) {
                const auto start = Clock::now();
                std::string bytes;
                {
                    std::ifstream in(mesh_file.string(), std::ios::binary);
                    std::ostringstream buffer;
                    buffer << in.rdbuf();
                    bytes = buffer.str();
                }
                const double read_ms = ms_since(start);
                const auto hash_start = Clock::now();
                const std::string digest = Agent::sha256_hex(bytes);
                const double sha_ms = ms_since(hash_start);
                std::cerr << "BENCH HASH triangles=" << triangles << " run=" << run << " bytes=" << bytes.size()
                          << " read_ms=" << read_ms << " sha256_ms=" << sha_ms << " total_ms=" << ms_since(start)
                          << " sha256=" << digest.substr(0, 16) << '\n';
            }

            // 5. Round trip: rotate, write a new thin file, assemble a restore folder, load it back.
            roundtrip(triangles, mesh_file);
        }

        settle(2, [self = shared_from_this()] { self->run_next_size(); });
    }

    void roundtrip(std::size_t triangles, const fs::path& mesh_file)
    {
        boost::system::error_code ec;
        Model& model = m_plater->model();
        ModelObject* object = model.objects.front();
        const std::string object_name = object->name;
        const double rotation_z = M_PI / 4.0;
        object->instances.front()->set_rotation(Vec3d(0.0, 0.0, rotation_z));
        m_plater->update();

        const fs::path restore_dir = m_state->scratch / ("restore-" + std::to_string(triangles));
        fs::remove_all(restore_dir, ec);
        fs::create_directories(restore_dir / "3D" / "Objects", ec);
        const fs::path thin = restore_dir / ".3mf";
        const int rc = m_plater->export_3mf(thin, SaveStrategy::Backup);
        const fs::path mesh_copy = restore_dir / "3D" / "Objects" / mesh_file.filename();
        fs::copy_file(mesh_file, mesh_copy, fs::copy_option::overwrite_if_exists, ec);
        std::cerr << "BENCH ROUNDTRIP_PREP triangles=" << triangles << " thin_rc=" << rc
                  << " thin_bytes=" << fs::file_size(thin, ec) << " mesh_copy=" << mesh_copy.string()
                  << " mesh_copy_bytes=" << fs::file_size(mesh_copy, ec) << " copy_ec=" << ec.message() << '\n';

        // Clear the plater first so load_project's close_with_confirm has nothing to ask about.
        if (m_plater->new_project(true, true) == wxID_CANCEL) {
            fail("new_project (pre-restore) cancelled");
            return;
        }
        // Restore load: originfile that is not "-", "<silence>", or "<loadall>" selects
        // LoadStrategy::Restore; the importer then resolves missing sub-model files under
        // "<filename minus .3mf>/", i.e. restore_dir.
        const auto start = Clock::now();
        std::string load_error;
        try {
            m_plater->load_project(wxString::FromUTF8(thin.string()), wxString());
        } catch (const std::exception& error) {
            load_error = error.what();
        }
        const double load_ms = ms_since(start);

        Model& loaded = m_plater->model();
        const std::size_t objects = loaded.objects.size();
        std::size_t facets = 0;
        Vec3d rotation(0, 0, 0);
        std::string loaded_name;
        if (objects > 0 && !loaded.objects.front()->volumes.empty() && !loaded.objects.front()->instances.empty()) {
            facets      = loaded.objects.front()->volumes.front()->mesh().facets_count();
            rotation    = loaded.objects.front()->instances.front()->get_rotation();
            loaded_name = loaded.objects.front()->name;
        }
        const bool ok = load_error.empty() && objects == 1 && facets == triangles &&
                        std::abs(rotation.x()) < 1e-6 && std::abs(rotation.y()) < 1e-6 &&
                        std::abs(rotation.z() - rotation_z) < 1e-6;
        std::cerr << "BENCH ROUNDTRIP triangles=" << triangles << " objects=" << objects << " facets=" << facets
                  << " rotation_x=" << rotation.x() << " rotation_y=" << rotation.y() << " rotation_z=" << rotation.z()
                  << " expected_z=" << rotation_z << " name=" << loaded_name << " orig_name=" << object_name
                  << " load_ms=" << load_ms << " backup_path_after=" << loaded.get_backup_path()
                  << " error=" << (load_error.empty() ? "-" : load_error) << " ok=" << (ok ? 1 : 0) << '\n';
    }

